 const title=document.querySelector('#china-selected-title'),desc=document.querySelector('#china-selected-description');
 const select=(p)=>{nearby.hidden=true;nearby.replaceChildren();title.textContent=p.name;desc.textContent=`${p.name} · 一座真实走过的城市。这里可以继续收藏与它有关的照片、食物和路上的记忆。`;nodeByName.forEach((node,name)=>{const active=name===p.name;node.classList.toggle('is-selected',active);node.setAttribute('aria-pressed',String(active));});list.querySelectorAll('button[data-city]').forEach(b=>{b.setAttribute('aria-pressed',String(b.dataset.city===p.name));});};
 const groups=[...new Set(PLACES.map(p=>p.group))];
 list.innerHTML=groups.map(group=>`<section class="china-city-group"><h3>${group}</h3><div class="china-city-pills">${PLACES.filter(p=>p.group===group).map(p=>`<button type="button" data-city="${p.name}" aria-pressed="false">${p.name}</button>`).join('')}</div></section>`).join('');
 let pointerType='',opener=null;
